script:
frappe.ui.form.on('Events', {
    setup: function(frm) {
        // Show ONLY top-level (parent) Event Types
        frm.set_query('type', function() {
            return {
                filters: {
                    parent_event_type: ["is", "not set"]
                }
            };
        });
        frm.set_query('category', function() {
            return {
                filters: {
                    parent_event_category: ["is", "not set"]
                }
            };
        });
    },

    onload: function(frm) {
        // Clear sub_type only for new documents
        if (frm.is_new()) {
            frm.set_value('sub_type', null);
            frm.set_value('subcategory', null);
        }

        // Disable sub_type until type is selected
        frm.toggle_enable('sub_type', false);
        frm.toggle_enable('subcategory', false);

        // Prevent any values from showing before type is selected
        frm.set_query('sub_type', function() {
            return {
                filters: { name: '__never__' }
            };
        });
        frm.set_query('subcategory', function() {
            return {
                filters: { name: '__never__' }
            };
        });
    },

    type: function(frm) {
        // Clear sub_type whenever parent changes
        frm.set_value('sub_type', null);

        // Enable sub_type only if type is selected
        frm.toggle_enable('sub_type', !!frm.doc.type);

        if (!frm.doc.type) {
            return;
        }

        // Filter sub_type to show only child Event Types
        frm.set_query('sub_type', function() {
            return {
                filters: {
                    parent_event_type: frm.doc.type,
                    is_group: 0
                }
            };
        });

        // UX: Inform user if no sub-types exist
        frappe.db.count('Event Type', {
            parent_event_type: frm.doc.type,
            is_group: 0
        }).then(count => {
            if (!count) {
                frappe.show_alert(
                    {
                        message: __('No sub-types available for this Event Type'),
                        indicator: 'orange'
                    },
                    5
                );
            }
        });

    },
    category: function(frm) {
        // Clear sub_type whenever parent changes
        frm.set_value('subcategory', null);

        // Enable sub_type only if type is selected
        frm.toggle_enable('subcategory', !!frm.doc.category);

        if (!frm.doc.category) {
            return;
        }

        // Filter sub_type to show only child Event Types
        frm.set_query('subcategory', function() {
            return {
                filters: {
                    parent_event_category: frm.doc.category,
                    is_group: 0
                }
            };
        });

        // UX: Inform user if no sub-types exist
        frappe.db.count('Event Category', {
            parent_event_category: frm.doc.category,
            is_group: 0
        }).then(count => {
            if (!count) {
                frappe.show_alert(
                    {
                        message: __('No sub-categories available for this Event Category'),
                        indicator: 'orange'
                    },
                    5
                );
            }
        });

    }
});
